using System;
using System.Diagnostics;
using System.Threading.Tasks;

// PROGRAM: Pembuktian Fenomena False Sharing Multi-Threading
public class FalseSharingDemo
{
    public long Counter1;
    public long Counter2; // Berada pada Cache Line 64-byte yang sama persis!
}

public class Program
{
    public static async Task Main()
    {
        var data = new FalseSharingDemo();
        const int Iterations = 50_000_000;

        var sw = Stopwatch.StartNew();

        // Dua thread independen menulis ke dua variabel berdampingan
        var t1 = Task.Run(() => {
            for (int i = 0; i < Iterations; i++) data.Counter1++;
        });

        var t2 = Task.Run(() => {
            for (int i = 0; i < Iterations; i++) data.Counter2++;
        });

        Task.WaitAll(t1, t2);
        sw.Stop();

        Console.WriteLine($"Eksekusi Selesai: {sw.ElapsedMilliseconds} ms");
        Console.WriteLine($"Counter1: {data.Counter1:N0} | Counter2: {data.Counter2:N0}");
        // TODO: Coba pisahkan kedua variabel ke struct terpisah dengan padding dan amati waktu yang terpangkas!
    }
}

