using System;

public class BranchPredictorOptimizer
{
    public static long SumFilteredSorted(int[] data, int threshold)
    {
        if (data == null || data.Length == 0) return 0;

        // Mengurutkan data menstabilkan pola percabangan (Branch Prediction Friendly)
        Array.Sort(data);

        long sum = 0;
        for (int i = 0; i < data.Length; i++)
        {
            if (data[i] >= threshold)
            {
                sum += data[i];
            }
        }

        return sum;
    }

    public static void Main()
    {
        int[] data = { 5, 1, 9, 3, 7, 2, 8, 4, 6 };
        Console.WriteLine($"Total >= 5: {SumFilteredSorted(data, 5)}");
    }
}
